def pruefe(eingabe):
    try:
        zahl = int(eingabe)
    except ValueError:
        print(eingabe, "ist keine Zahl.")
    else:
        print(eingabe, "ist die Zahl", zahl)
    finally:
        print("Pruefung beendet.")


