def teile(zahl, teiler):
    if teiler == 0:
        raise ValueError("Teiler darf nicht null sein")
    return zahl / teiler


def lies(pfad):
    try:
        with open(pfad, encoding="utf-8") as datei:
            return datei.read()
    except FileNotFoundError:
        print("Datei fehlt. Ich reiche den Fehler weiter.")
        raise


try:
    print("Ergebnis:", teile(10, 2))
    print("Ergebnis:", teile(10, 0))
except ValueError as fehler:
    print("Abgefangen:", fehler)

