def alter_pruefen(text):
    try:
        alter = int(text)
    except ValueError:
        print("Eingabe war", text, "- bitte nur Ziffern eingeben.")
        return None
    if alter < 0:
        print("Alter", alter, "ist negativ - bitte eine Zahl ab 0 eingeben.")
        return None
    return alter


print("Ergebnis:", alter_pruefen("siebenundzwanzig"))
print("Ergebnis:", alter_pruefen("-3"))
print("Ergebnis:", alter_pruefen("27"))

